<?php $prefix=$adminMode?'/admin/support/':'/support/';$statusLabels=['open'=>'منتظر پاسخ تیم','waiting'=>'در حال بررسی','answered'=>'پاسخ داده‌شده','closed'=>'بسته‌شده']; ?>
<section class="section support-page" lang="fa" dir="rtl"><div class="<?= $adminMode?'':'container' ?> support-thread-container">
<a class="btn btn--ghost" href="<?= $adminMode?'/admin/support':'/support' ?>">همهٔ گفتگوها</a><header class="support-heading"><div><span class="eyebrow">پشتیبانی منتوریس</span><h1><?= e($ticket['subject']) ?></h1><span class="badge badge--neutral" data-ticket-status><?= e($statusLabels[$ticket['status']] ?? $ticket['status']) ?></span></div><?php if($adminMode && \App\Core\Authorization::can($admin,'engagements.manage') && $ticket['status']!=='closed'): ?><form action="/admin/support/<?= e($ticket['id']) ?>/close" method="post"><?= csrf_field() ?><button class="btn btn--secondary">بستن گفتگو</button></form><?php endif; ?></header>
<?php if($notice): ?><p class="alert"><?= e($notice) ?></p><?php endif; ?>
<section class="support-conversation" data-support-thread="<?= e($prefix.$ticket['id']) ?>"><div data-support-messages aria-live="polite" aria-relevant="additions"><?php foreach($messages as $item): require view_path('components/support-message.php'); endforeach; ?></div><p class="support-sync" data-support-sync role="status">پاسخ‌های تازه در همین صفحه نمایش داده می‌شوند. زمان پاسخ به حضور تیم بستگی دارد.</p></section>
<?php if($canReply && $ticket['status']!=='closed'): ?><form class="support-reply" action="<?= e($prefix.$ticket['id']) ?>/reply" method="post" enctype="multipart/form-data" data-support-form data-support-draft="<?= e($user['id'].'-'.$ticket['id']) ?>"><?= csrf_field() ?><label class="form-group"><span class="form-label"><?= $adminMode?'پاسخ تیم':'پیام بعدی شما' ?></span><textarea class="form-control" name="message" rows="4" maxlength="4000" placeholder="پیام را بنویسید…"></textarea></label><label class="form-group"><span class="form-label">صوت یا فایل تا ۸ مگابایت</span><input class="form-control" type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.mp3,.ogg,.wav,.m4a,.webm,.txt,.docx,.xlsx,.pptx"></label><p data-support-status role="status"></p><button class="btn btn--primary">ارسال پیام <?= icon('arrow-left') ?></button></form><?php else: ?><p class="user-panel">این گفتگو بسته است یا دسترسی ارسال پاسخ ندارید.</p><?php endif; ?>
</div></section>
